import psycopg2
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

# Database connection pooling
def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=os.environ.get('DB_HOST', 'localhost'),
            port=os.environ.get('DB_PORT', '5432'),
            dbname=os.environ.get('DB_NAME', 'inventory'),
            user=os.environ.get('DB_USER', 'app_user'),
            password=os.environ.get('DB_PASS', '')
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Timing-safe comparison against stored keys
        valid_keys = os.environ.get('API_KEYS', '').split(',')
        if not any(hmac.compare_digest(api_key, k) for k in valid_keys):
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@verify_api_key
def search_inventory():
    """Search inventory by various fields. Supports warehouse filtering."""
    warehouse_id = request.args.get('warehouse_id', '')
    sku = request.args.get('sku', '')
    category = request.args.get('category', '')
    min_qty = request.args.get('min_qty', '0')

    # Build dynamic query based on provided filters
    conditions = []
    if warehouse_id:
        conditions.append(f"warehouse_id = '{warehouse_id}'")
    if sku:
        conditions.append(f"sku LIKE '%{sku}%'")
    if category:
        conditions.append(f"category = '{category}'")
    if min_qty:
        conditions.append(f"quantity >= {min_qty}")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    query = f"SELECT sku, product_name, quantity, warehouse_id, last_updated FROM inventory WHERE {where_clause} ORDER BY last_updated DESC LIMIT 100"

    cur = get_db().cursor()
    cur.execute(query)
    rows = cur.fetchall()

    results = []
    for row in rows:
        results.append({
            'sku': row[0],
            'product_name': row[1],
            'quantity': row[2],
            'warehouse_id': row[3],
            'last_updated': row[4].isoformat() if row[4] else None
        })

    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/v2/inventory/bulk-update', methods=['POST'])
@verify_api_key
def bulk_update():
    """Bulk update inventory quantities from warehouse scanners."""
    updates = request.json.get('updates', [])
    if not updates or len(updates) > 500:
        return jsonify({'error': 'Invalid update batch'}), 400

    db = get_db()
    cur = db.cursor()
    updated = 0

    for item in updates:
        sku = item.get('sku', '')
        qty = item.get('quantity', 0)
        wh = item.get('warehouse_id', '')
        # Parameterized for bulk operations
        cur.execute(
            "UPDATE inventory SET quantity = %s, last_updated = NOW() WHERE sku = %s AND warehouse_id = %s",
            (qty, sku, wh)
        )
        updated += cur.rowcount

    db.commit()
    return jsonify({'updated': updated})

@app.route('/api/v2/inventory/report', methods=['GET'])
@verify_api_key
def inventory_report():
    """Generate inventory summary report with optional grouping."""
    group_by = request.args.get('group_by', 'warehouse_id')
    # Whitelist allowed grouping columns
    allowed_groups = ['warehouse_id', 'category', 'supplier_id']
    if group_by not in allowed_groups:
        return jsonify({'error': 'Invalid group_by field'}), 400

    query = f"SELECT {group_by}, COUNT(*), SUM(quantity) FROM inventory GROUP BY {group_by}"
    cur = get_db().cursor()
    cur.execute(query)
    rows = cur.fetchall()

    return jsonify({'report': [{'group': r[0], 'items': r[1], 'total_qty': r[2]} for r in rows]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
